Method.Implementation:
	#dim locArray As array Of %String;
    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("In OnGetConnections")
	Set (tValue,tIndex)=""
	For {
    Set tIndex = item.Settings.Next(tIndex)
     Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Setting: " _ item.Name)
     Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( item.GetSetting("NextOperation"))
     Quit:tIndex=""
    Set tSetting = item.Settings.GetAt(tIndex)
    If tSetting.Name="NextOperation" {
	     Set tValue=tSetting.Value
	     Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(tSetting.Name + ": " _ tValue)

    }
  }

 For i=1:1:$L(tValue,",") {
   Set tOne=$P(tValue,",",i)
   Continue:""=tOne
   Set pArray(tOne)=""
  }

	#dim locArray as list Of Ens.Config.Setting
	#dim settingVal as  Ens.Config.Setting
	set tSC = $$$OK

	set operValue = ""
	set prodNm = ##class(Ens.Director).GetActiveProductionName()
	if (prodNm = "")
	{
		Quit $$$ERROR("Can not get production name")
	}
	//Get exisiting value
	Set SQLCODE=0
	&sql(Select ID,Name	Into :xID,:name
		From Ens_Config.Item 
		Where Name=:itNm)

	if (SQLCODE = 0)
	{
	    set itm = ##class(Ens.Config.Item).%OpenId(xID)
	    $$$LOGINFO(itm.Name _ " - " _ xID)
	    set locArray = itm.Settings
	    Set key = locArray.Next("")

	 	while (key '= "")
	 	{
			set settingVal = locArray.GetAt(key)
  			if (settingVal.Name = "NextOperation")
  			{
	  		 	set operValue = settingVal.Value
	  		 	break	  		
  			}
  			Set key = locArray.Next(key)
	 	}
	 }
	 // Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("exisiting oper: " _ operValue)
	 if ( $FIND(operValue, newVal) <= 0)
	 {
	 	if ( $LENGTH(operValue) > 0)
	 	{
	 		set operValue = operValue _ "," _ newVal
	 	}
	 	else
	 	{
		 	set operValue = newVal
	 	}
	 	set pArray(itNm, "Host", "NextOperation") = operValue

	 	set tSC = ##class(Ens.Production).ApplySettings(prodNm, .pArray)
	 	$$$LOGINFO("ApplySettings: " _ operValue)
	 }
	 return tSC
